import{_ as r,a as p}from"./chunks/d0b9fe99662ac4726518.BHKI3Z40.js";import{_ as n,C as o,o as s,c as i,j as a,a as m,E as l,a5 as h}from"./chunks/framework.DNkHA0lr.js";const y=JSON.parse('{"title":"我给自己洗脑，让自己变得自信","description":"","frontmatter":{"title":"我给自己洗脑，让自己变得自信","originalTitle":"I Brainwashed Myself Into Being Confident","date":"2022-02-25","originalUrl":"https://thedankoe.com/letters/i-brainwashed-myself-into-being-confident/","minutes":10,"sourceHash":"fb279cf935cd306ff1fd44139b2bb1bdb5959dbf98f320ad26ac9c6f467fd981","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/i-brainwashed-myself-into-being-confident/"}]]},"headers":[],"relativePath":"letters/i-brainwashed-myself-into-being-confident.md","filePath":"letters/i-brainwashed-myself-into-being-confident.md"}'),d={name:"letters/i-brainwashed-myself-into-being-confident.md"};function c(f,e,b,g,u,_){const t=o("ArticleMeta");return s(),i("div",null,[e[0]||(e[0]=a("h1",{id:"我给自己洗脑-让自己变得自信",tabindex:"-1"},[m("我给自己洗脑，让自己变得自信 "),a("a",{class:"header-anchor",href:"#我给自己洗脑-让自己变得自信","aria-label":'Permalink to "我给自己洗脑，让自己变得自信"'},"​")],-1)),l(t),e[1]||(e[1]=h('<p><a href="https://www.youtube.com/embed/2nKVKwpRYII?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>这不会是又一篇冥想指南。我也不会在这里教你给生活增添更多物质。这更不是什么“速成技巧或捷径”。</p><p>这一系列的概念，你必须要理解。</p><p>这篇通讯的标题本来可以是：</p><p><em>“如何获得快乐。”</em></p><p><em>“过上好日子唯一需要的东西。”</em></p><p><em>“如何生活。”</em></p><p>这个概念对于在现代世界中游刃有余至关重要。慢慢读。做好笔记，并付诸实践。</p><p>这需要时间。你花了一辈子的时间才被文化规训成现在这种不快乐的状态。要解除植入你脑海中的负面程序，可能需要数年时间——也可能只需在一个臣服的瞬间就能完成。</p><p>我们先从阿兰·瓦茨（Alan Watts）的一段话开始：</p><blockquote><p><em>一个无时无刻不在思考的人，除了思想之外无物可想。因此，他失去了与现实的联系，生活在幻觉的世界里。我所说的思考，特指“头脑中的喋喋不休”……对词语无休止的、强迫性的重复……充满计较与算计。</em></p><p><em>我不是说思考不好。就像其他所有事情一样，适度是有益的。它是一个好仆人，却是一个坏主人——所有所谓的文明人，正变得越来越疯狂和自我毁灭。由于过度思考，他们失去了与现实的联系。</em></p><p><em>我们中的大多数人宁愿要金钱也不要看得见摸得着的财富……一个盛大的场合，如果不拍照，总觉得被破坏了……而第二天在报纸上读到它的报道，对我们来说竟然莫名其妙地比参与原本的事件还要有趣。这是一场灾难。</em></p><p><em>要接触现实，有一种冥想的艺术……这是一种让头脑暂时安静下来的艺术……停止“头脑中的喋喋不休”。当然，你不能强迫你的头脑安静下来。那就像试图用电熨斗去熨平水面的涟漪。水只有在不被打扰的时候，才会变得清凉澄澈。</em></p><p>阿兰·瓦茨（Alan Watts）</p></blockquote><h2 id="你已经被规训成了平庸之辈" tabindex="-1"><strong>你已经被规训成了平庸之辈</strong> <a class="header-anchor" href="#你已经被规训成了平庸之辈" aria-label="Permalink to &quot;**你已经被规训成了平庸之辈**&quot;">​</a></h2><p>什么是“规训（conditioning）”？想想健身房。你通过重复某项特定的运动来锻炼（condition）自己。结果就是，你增加了肌肉或心肺功能。如果你不去健身房，你也是在执行会导致相反结果的重复动作。没有中间地带。你要么在成长，要么在衰退。肌肉的微小增加、脂肪的微小增加、肌肉的微小减少、脂肪的微小减少。重复往往在不知不觉中发生。</p><p>思想上的文化规训就是这里的敌人。这也是导致你过度<em>“头脑中喋喋不休”</em>的原因。是那个让你持续不快乐的罪魁祸首。思想、信念、偏见、反应、意识形态、政治立场，以及所有其他模糊你感知的东西。那些通过重复被强行敲进你脑子里的外部投射。</p><p>为了这封邮件的讨论，你的感知就是你的世界观。你解释事物的方式。你观察事物的“镜头”。文化规训“模糊”了这个“镜头”。作为一个孩子，你生活在没有这种规训的自然状态中。你贪玩、充满爱心且充满好奇。随着年龄的增长，这些特质被压抑了。它们被规训模糊了。这种规训阻碍了你“看清”事物的本来面目。</p><p><img src="'+r+'" alt=""></p><p>感知 VS 现实</p><p>一边是感知，基于你所扮演角色的镜头。你的性格、信念和偏见。另一边是现实，基于真实的你是谁。真理。上帝。意识。存在的本来面目。万物之源。宇宙。无论你想怎么称呼它。不同的信仰体系有不同的叫法。有些人采用这些感知的镜头，是为了过上更接近真理的生活。</p><h2 id="将-存在-与-变成-区分开来" tabindex="-1"><strong>将“存在”与“变成”区分开来</strong> <a class="header-anchor" href="#将-存在-与-变成-区分开来" aria-label="Permalink to &quot;**将“存在”与“变成”区分开来**&quot;">​</a></h2><p>你<em>以为</em>你是谁，那并不是真正的你。<em>你是谁，取决于你正在做什么。</em> 而不是你做过什么。真实的你，是与生命一同流动的“存在（being）”。当你走在路上，你看到建筑物、树木、街道，以及其他即使你身在数英里外也将与你一起<em>存在（be）</em>在那里的东西。它们并没有被留在过去。它们没有受制于时间的信念和情绪。除非被摧毁，否则这栋建筑两年后还会在这里。除非被摧毁，否则两年后你也会在这里。而你的思想、情绪和感受则不会。负面情绪在现实中是无法存在的。</p><p>你<em>以为</em>你是谁，只是你在扮演的一个角色。<em>是你正在“变成（becoming）”的那个人。</em> 是你为了融入社会而穿上的伪装。是头脑的捏造。是猖獗的——或受控的——思考的结果。思想，通过你的聚焦被赋予了生命。再通过感知，转化成了负面的情绪和感受。是对你接触到的外部刺激所做出的自动且无意识的反应。<strong>你聚焦的准确度，将决定你在生活中承受多少痛苦。</strong></p><p>我们都有超越自我的渴望。想要去完完全全地服务于万物之源、宇宙、上帝等。在做这些之前，我们必须先实现自我实现（self-actualize）。有些人可能对马斯洛需求层次理论很熟悉。</p><p><img src="'+p+'" alt=""></p><p>马斯洛需求层次理论</p><p>意思是说，在自我超越之前，我们必须先实现自我实现。<a href="https://join.modernmastery.co/?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">去健身，开始创业，获得独立，并滋养我们的心灵。</a> 为了实现自我，我们必须玩这场人生游戏。为了玩这场游戏，我们必须首先<em>创造</em>我们的角色。有意识地去创造。不是通过文化规训。<em>而是通过有意识的规训。</em></p><p>我们的目标是<em>觉察</em>到这种分离并弥合鸿沟。弥合现实与概念之间的鸿沟。上帝与“上帝”这个词之间的鸿沟。自然与捏造。无形与有形。光明与黑暗。爱与恨。真理与谎言。剥离那些对你无益的感知，让你的行动由内驱力驱动（更接近真理）——而不是由外部指派（阻碍真理）。</p><blockquote><p><em>移除你头脑中的障碍，你就拥有了智慧。移除你心中的障碍，你就拥有了爱。</em></p></blockquote><p>你必须意识到，你的角色（你正在成为的那个人）是为了服务你而存在的。你的信念是具有可塑性的。你的负面想法可以在任何时刻被转化为积极的——更接近真理的想法。我们必须通过重复积极的想法、信念和行动来塑造这个角色，推动我们走向生活中积极的结果。</p><p>这将让你能够吸引和建立那些能带来金钱、意义、健康以及其他曾被错误感知所掩盖的事物。最终让你能够超越自己，并传承你的经验教训（根据古代和现代导师的说法，这就是生活意义的精髓）。</p><p><a href="https://links.modernmastery.co/?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">我在今天的播客中更深入地探讨了整个“存在 VS 变成”的话题。它或许能帮你更好地理解。</a></p><h2 id="有意识的规训过程" tabindex="-1"><strong>有意识的规训过程</strong> <a class="header-anchor" href="#有意识的规训过程" aria-label="Permalink to &quot;**有意识的规训过程**&quot;">​</a></h2><p>通过有意识的规训，你创造出属于你自己的“镜头”来观察这个世界。你能更准确地感知事物。你升级了你的大脑程序。你要么被文化规训走向失败和平庸——要么你可以有意识地规训你的角色，走向有利的结果。要么去编程，要么被编程。</p><p>在你进行这个过程之前，你可能需要先读一读<a href="https://thedankoe.com/how-to-create-a-life-of-meaning-money-impact-as-fast-as-humanly-possible/" target="_blank" rel="noreferrer">创造金字塔</a>并下载<a href="https://shop.thedankoe.com/planner?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">力量计划表</a>。这将为你提供额外的指引和一路完善的东西。结构才是王道，但干扰依然会找上门来。它们是不可避免的。这个过程将帮助你应对它们，并将负能量转化为正能量。</p><p>你将规训你的注意力集中在积极的事物上，从而让这个过程变成一种习惯。你目前的思维过程是花了数年时间才固化下来的。这是一场终生的旅程和实践。</p><p>这是一个分6步的过程：</p><h3 id="_1-暂停" tabindex="-1"><strong>1) 暂停</strong> <a class="header-anchor" href="#_1-暂停" aria-label="Permalink to &quot;**1) 暂停**&quot;">​</a></h3><p>当一个想法跳进你的脑海时，在它变成情绪、信念、特质或反应之前，先暂停一下。这需要练习。</p><p>如果这个想法立刻变质发臭，把你的注意力转移到我称之为“锚点（anchors）”的东西上。锚点是安放你注意力的地方，用来中和并转化负面的感受和情绪。</p><p><em>呼吸</em>是你最唾手可得的工具。有些人通过正念冥想来做计划安排。但你随时都可以把注意力集中在你的呼吸上。</p><p>其他的锚点还包括音乐、大自然沐浴、身体运动、写日记（我们稍后会讨论），以及任何其他意味着潜在的心流状态或压力调节的活动。</p><h3 id="_2-提问" tabindex="-1"><strong>2) 提问</strong> <a class="header-anchor" href="#_2-提问" aria-label="Permalink to &quot;**2) 提问**&quot;">​</a></h3><p>问自己一些能揭示这个想法真实本质的问题。</p><p><em>“我为什么会这样想？”</em></p><p><em>“我以前有过这种想法吗？它导向了什么结果？”</em></p><p><em>“这理性吗？我应该在这个想法上投入能量吗？”</em></p><p>让问题引发更多的问题。这能让觉知之光照亮盲区，并可能彻底消解潜在的问题。</p><p>下一个最好的方法是通过 CC（有意识的规训）写日记。把你的想法写在纸上。写下那些问题，并当场回答它们。这是一个必须要培养的关键习惯。把想法落在纸上能提供立竿见影的释放。这是一种不可思议的自我觉察练习。</p><p><strong>提问。至关。重要。</strong></p><p>这是最重要的一步。为什么？因为理解。这是你揭开错误感知根源究竟在何处的地方。</p><p>如果你没有意识到你的执念以及你身份中的负面成分，习惯养成和其他自助建议都是毫无价值的。<em>你必须直击根源。</em> 质疑你的想法，直到它们触动你的神经。直到你感觉到那股负能量在积聚。从这股能量中，你已经把觉知的光芒照在了这个问题上。现在，你可以朝着相反的方向努力了。</p><p>你无法理解一个潜在的积极未来。你只能理解一个消极且熟悉的过去。现在你就有了一个可以摆脱的起点。朝着那个潜在的积极未来迈进。</p><p>举个例子，“我很懒”不足以作为一个要摆脱的起点。你执着于什么东西让你变得懒惰？比起揭开并理解这个障碍，任何关于生产力的建议都帮不上什么大忙。</p><h3 id="_3-客体化" tabindex="-1"><strong>3) 客体化</strong> <a class="header-anchor" href="#_3-客体化" aria-label="Permalink to &quot;**3) 客体化**&quot;">​</a></h3><p>明白这个想法——或者你所揭露出的那个负面反应——并不是<em>你</em>的一部分。它是一个客体。一个独立的实体。只有当你聚焦于它时，它才被赋予了生命。这是一个可用于毁灭或创造你这个角色的工具。</p><p>把这个和你的想法一起写下来。</p><h3 id="_4-重构" tabindex="-1"><strong>4) 重构</strong> <a class="header-anchor" href="#_4-重构" aria-label="Permalink to &quot;**4) 重构**&quot;">​</a></h3><p>现在你要把自我毁灭的负面因素变成自我创造的正面因素。注入你的意识。将其变成能够推动你走向最佳结果、实现你的愿景、目标和优先事项的东西。</p><p>这里有几个重构的例子：</p><p><strong>把内疚变成感激</strong> —— 乔克·威林克（Jocko Willink）在军队服役期间，曾因为离开自己的团队而感到内疚。他必须有意识地将这种负面信念规训为能够回家的感激之情。</p><p><strong>从失败到成功</strong> —— 要明白，一次失败只是一种反馈。它是成功阶梯上的一级。</p><p><strong>从自我安慰到好奇心</strong> —— 当一个机会出现时（比如大多数在线商业机会、这种有意识的条件反射过程等等），不要封闭内心去抗拒它，而是保持开放的心态并问问自己：“如果我尝试一下会发生什么？”</p><p>如果你想更深入地理解这一点，去研究一下两极性（polarity）。恐惧与爱对立——并且可以转化为爱。所有的负面事物也是如此。</p><h3 id="_5-塑造特征" tabindex="-1"><strong>5) 塑造特征</strong> <a class="header-anchor" href="#_5-塑造特征" aria-label="Permalink to &quot;**5) 塑造特征**&quot;">​</a></h3><p>你该如何利用这种认知的重塑来推动自己向积极的方向发展？你可以采取什么行动？有什么是你<em>能</em>做的吗？</p><p>向耶稣、精神导师以及与你“同频”的正面榜样等令人向往的理想原型请教。在你的处境下，他们会怎么做？</p><h3 id="_6-保持一致" tabindex="-1"><strong>6) 保持一致</strong> <a class="header-anchor" href="#_6-保持一致" aria-label="Permalink to &quot;**6) 保持一致**&quot;">​</a></h3><p>提醒自己根据《创造层级表》（The Creation Hierarchy）设定的愿景、目标和优先事项，以及这种积极的特质将如何帮助你在这条道路上前行。</p><p>保持一致 = 让你的角色行为与真实的你相符。采取积极的、真实的、如神明般的行动，这些行动将带来自我实现（开明的自私）、自我超越（开明的无私），以及人间天堂。推动人类集体意识的进步。扮演好你的角色并传播积极的信息。</p><p><strong>这。需。要。时。间。</strong></p><p>在听一堂 Actualized 讲座时（我每天晚上都会听哲学讲座，为了进行“大局观思考”并借此入睡），主讲人提到了学习哲学的重要性。我们总是会被生活中的技术细节所困扰，而实际上它们毫无意义。技术细节解决的是技术问题。你不是一台技术设备。你是一团汇聚在一起的意识，可能永远无法被完全理解。</p><p>学习哲学和灵性会让你的大脑进入“大局观思考”模式。我无法解释这种现象，但通过每天的学习——我的日子变得没有压力，也不再忧虑。我“没那么在乎”了。随着我凭着不被技术性思维阻碍的直觉去行动，一切自然水到渠成。</p><p>讲座中还提到，开始理解这些哲学概念需要几年的时间——然后你会突然茅塞顿开。所有这些灵性的东西此刻正一齐向我涌来。有些事说不通，这反而是合理的，而我们所有问题的根源，恰恰就在于非要试图把它们说通。</p><p>通过不去强求说得通，你得以存在，并逐渐与真理（Truth）保持一致。</p><p><em>丹·柯（Dan Koe）</em></p><hr><p><a href="/en/letters/i-brainwashed-myself-into-being-confident">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',76))])}const w=n(d,[["render",c]]);export{y as __pageData,w as default};
